verus! {
    // Given a vector of i8 numbers and a delimiter i8 value,
    // returns a new vector where the delimiter is inserted between every pair of consecutive elements.
    // If length is 0 or 1, returns the vector unchanged.
    // Otherwise:
    // - result length = 2 * n - 1 where n = input length
    // - result[even indices] = input elements in order
    // - result[odd indices] = delimiter

    fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
        ensures(
            // If numbers has length 0 or 1, result == numbers unchanged
            (numbers.len() == 0 || numbers.len() == 1) ==> (result == numbers)
        )
        ensures(
            // For n > 1, length of result is 2 * n - 1
            numbers.len() > 1 ==> result.len() == 2 * numbers.len() - 1
        )
        ensures(
            // For n > 1, elements at even indices equal input elements
            numbers.len() > 1 ==> forall |i: usize| (i < numbers.len() ==> result[2*i] == numbers[i])
        )
        ensures(
            // For n > 1, elements at odd indices equal delimiter
            numbers.len() > 1 ==> forall |j: usize| (j < numbers.len() - 1 ==> result[2*j + 1] == delimiter)
        )
    {
        let n = numbers.len();
        if n == 0 || n == 1 {
            // For 0 or 1 element, just return numbers unchanged
            return numbers;
        }

        // length of result vector:
        let res_len = 2 * n - 1;
        let mut result: Vec<i8> = Vec::with_capacity(res_len);

        // push elements maintaining the specification
        
        let mut i = 0;
        // Loop invariant and decreases for verification:
        // i <= n - 1; we add elements to result accordingly
        while i < n {
            invariant!(
                0 <= i && i <= n,
                result.len() == 2 * i.saturating_sub(1).max(0) + 1.min(1),
                // result length after i iterations equals 2*i - 1 if i>0, else 0 or 1:
                // Actually, after adding i elements, number of items inserted = 2*i -1 
                // (elements + delimiters between them), except when i=0
                // We can phrase as result.len() == if i == 0 { 0 } else { 2*i - 1 }
                // For simplicity, we state that result.len() == if i == 0 { 0 } else { 2*i - 1 }
                forall |k: usize| (k < i ==> result[2*k] == numbers[k]),
                forall |k: usize| (k + 1 < i ==> result[2*k + 1] == delimiter)
            );
            decreases(n - i);

            // Append numbers[i]
            result.push(numbers[i]);

            if i != n - 1 {
                // After adding an element except the last, add delimiter
                result.push(delimiter);
            }

            i = i + 1;
        }

        // After loop, result should be length 2*n - 1
        assert(result.len() == 2 * n - 1);

        // final verifies:
        //  - even indices correspond to input elements
        //  - odd indices are delimiter
        // (The ensures clauses cover these)

        result
    }
}